// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListApiKeys Active API keys
	// (GET /v1/admin/api-keys)
	ListApiKeys(ctx context.Context, request ListApiKeysRequestObject) (ListApiKeysResponseObject, error)
	// CreateApiKey Create an API key for an integration
	// (POST /v1/admin/api-keys)
	CreateApiKey(ctx context.Context, request CreateApiKeyRequestObject) (CreateApiKeyResponseObject, error)
	// RevokeApiKey Revoke an API key; it stops working at once
	// (DELETE /v1/admin/api-keys/{id})
	RevokeApiKey(ctx context.Context, request RevokeApiKeyRequestObject) (RevokeApiKeyResponseObject, error)
	// ListAuditLog Who changed what, newest first
	// (GET /v1/admin/audit-log)
	ListAuditLog(ctx context.Context, request ListAuditLogRequestObject) (ListAuditLogResponseObject, error)
	// AdminListBanners Every banner, hidden ones included
	// (GET /v1/admin/banners)
	AdminListBanners(ctx context.Context, request AdminListBannersRequestObject) (AdminListBannersResponseObject, error)
	// CreateBanner Add a banner
	// (POST /v1/admin/banners)
	CreateBanner(ctx context.Context, request CreateBannerRequestObject) (CreateBannerResponseObject, error)
	// DeleteBanner Remove a banner
	// (DELETE /v1/admin/banners/{id})
	DeleteBanner(ctx context.Context, request DeleteBannerRequestObject) (DeleteBannerResponseObject, error)
	// UpdateBanner Change a banner
	// (PUT /v1/admin/banners/{id})
	UpdateBanner(ctx context.Context, request UpdateBannerRequestObject) (UpdateBannerResponseObject, error)
	// CreateCategory Add a category
	// (POST /v1/admin/categories)
	CreateCategory(ctx context.Context, request CreateCategoryRequestObject) (CreateCategoryResponseObject, error)
	// DeleteCategory Remove a category
	// (DELETE /v1/admin/categories/{id})
	DeleteCategory(ctx context.Context, request DeleteCategoryRequestObject) (DeleteCategoryResponseObject, error)
	// UpdateCategory Rename, move or reorder a category
	// (PUT /v1/admin/categories/{id})
	UpdateCategory(ctx context.Context, request UpdateCategoryRequestObject) (UpdateCategoryResponseObject, error)
	// AdminOverview The numbers on the dashboard's home page
	// (GET /v1/admin/overview)
	AdminOverview(ctx context.Context, request AdminOverviewRequestObject) (AdminOverviewResponseObject, error)
	// AdminListProducts Every product, drafts and archived included, newest first
	// (GET /v1/admin/products)
	AdminListProducts(ctx context.Context, request AdminListProductsRequestObject) (AdminListProductsResponseObject, error)
	// CreateProduct Add a product
	// (POST /v1/admin/products)
	CreateProduct(ctx context.Context, request CreateProductRequestObject) (CreateProductResponseObject, error)
	// DeleteProduct Remove a product for good
	// (DELETE /v1/admin/products/{id})
	DeleteProduct(ctx context.Context, request DeleteProductRequestObject) (DeleteProductResponseObject, error)
	// AdminGetProduct One product, whatever its status
	// (GET /v1/admin/products/{id})
	AdminGetProduct(ctx context.Context, request AdminGetProductRequestObject) (AdminGetProductResponseObject, error)
	// UpdateProduct Replace a product's details, options, variants and images
	// (PUT /v1/admin/products/{id})
	UpdateProduct(ctx context.Context, request UpdateProductRequestObject) (UpdateProductResponseObject, error)
	// UpdateStore Change the shop's settings
	// (PUT /v1/admin/store)
	UpdateStore(ctx context.Context, request UpdateStoreRequestObject) (UpdateStoreResponseObject, error)
	// UploadImage Upload a JPEG, PNG or WebP image, up to 10 MB
	// (POST /v1/admin/uploads)
	UploadImage(ctx context.Context, request UploadImageRequestObject) (UploadImageResponseObject, error)
	// AdjustStock Add to or take from a variant's stock, saying why
	// (POST /v1/admin/variants/{id}/stock-adjustments)
	AdjustStock(ctx context.Context, request AdjustStockRequestObject) (AdjustStockResponseObject, error)
	// Login Sign in with email or phone and password
	// (POST /v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout End this session
	// (POST /v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Refresh Swap a refresh token for a new pair
	// (POST /v1/auth/refresh)
	Refresh(ctx context.Context, request RefreshRequestObject) (RefreshResponseObject, error)
	// Register Create a customer account and sign in
	// (POST /v1/auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// ListBanners The shop's active banners, in display order
	// (GET /v1/banners)
	ListBanners(ctx context.Context, request ListBannersRequestObject) (ListBannersResponseObject, error)
	// ListBrands Brands with products for sale, most products first
	// (GET /v1/brands)
	ListBrands(ctx context.Context, request ListBrandsRequestObject) (ListBrandsResponseObject, error)
	// GetCart The shopper's cart
	// (GET /v1/cart)
	GetCart(ctx context.Context, request GetCartRequestObject) (GetCartResponseObject, error)
	// SetCartItem Set how many of a variant are in the cart
	// (PUT /v1/cart/items/{variant_id})
	SetCartItem(ctx context.Context, request SetCartItemRequestObject) (SetCartItemResponseObject, error)
	// MergeCart Move a guest cart into the signed-in customer's cart
	// (POST /v1/cart/merge)
	MergeCart(ctx context.Context, request MergeCartRequestObject) (MergeCartResponseObject, error)
	// ListCategories Every category, in display order
	// (GET /v1/categories)
	ListCategories(ctx context.Context, request ListCategoriesRequestObject) (ListCategoriesResponseObject, error)
	// GetHealth Is the API up and can it reach its database
	// (GET /v1/health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetMe The signed-in user
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// SubscribeNewsletter Sign an email up for the shop's news and offers
	// (POST /v1/newsletter)
	SubscribeNewsletter(ctx context.Context, request SubscribeNewsletterRequestObject) (SubscribeNewsletterResponseObject, error)
	// ListProducts Products for sale, filtered and sorted
	// (GET /v1/products)
	ListProducts(ctx context.Context, request ListProductsRequestObject) (ListProductsResponseObject, error)
	// GetProduct One product for sale, with its variants and images
	// (GET /v1/products/{slug})
	GetProduct(ctx context.Context, request GetProductRequestObject) (GetProductResponseObject, error)
	// GetStore The shop's public settings
	// (GET /v1/store)
	GetStore(ctx context.Context, request GetStoreRequestObject) (GetStoreResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListApiKeys operation middleware
func (sh *strictHandler) ListApiKeys(w http.ResponseWriter, r *http.Request) {
	var request ListApiKeysRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListApiKeys(ctx, request.(ListApiKeysRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListApiKeys")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListApiKeysResponseObject); ok {
		if err := validResponse.VisitListApiKeysResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

// CreateApiKey operation middleware
func (sh *strictHandler) CreateApiKey(w http.ResponseWriter, r *http.Request) {
	var request CreateApiKeyRequestObject

	var body CreateApiKeyJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.CreateApiKey(ctx, request.(CreateApiKeyRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "CreateApiKey")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(CreateApiKeyResponseObject); ok {
		if err := validResponse.VisitCreateApiKeyResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

